CREATE OR REPLACE FUNCTION public.payment_ingest() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE p public.publisher_payment_policy; r record; b public.publisher_earnings_batches; BEGIN
p:=public.payment_policy_current(); FOR r IN SELECT user_id,'website'::text source,date AS earning_day,sum(revenue*pr.revenue_share/100)::numeric(20,6) gross FROM public.revenue_events e JOIN public.profiles pr ON pr.id=e.user_id WHERE site_id IS NOT NULL AND date>=(p.effective_at AT TIME ZONE 'UTC')::date GROUP BY user_id,date UNION ALL SELECT n.user_id,'smartlink',stat_date,sum(n.revenue*pr.revenue_share/100)::numeric(20,6) FROM public.network_stats n JOIN public.profiles pr ON pr.id=n.user_id WHERE n.source='api' AND stat_date>=(p.effective_at AT TIME ZONE 'UTC')::date GROUP BY n.user_id,stat_date LOOP
PERFORM pg_advisory_xact_lock(hashtext(r.user_id::text)); SELECT * INTO b FROM public.publisher_earnings_batches WHERE user_id=r.user_id AND source=r.source AND period_start=r.earning_day AND period_end=r.earning_day FOR UPDATE;
IF NOT FOUND THEN INSERT INTO public.publisher_earnings_batches(user_id,source,period_start,period_end,gross,verification_ends_at) VALUES(r.user_id,r.source,r.earning_day,r.earning_day,greatest(0,r.gross),greatest(now(),(r.earning_day+1)::timestamp AT TIME ZONE 'UTC')+make_interval(days=>p.verification_days)) RETURNING * INTO b; INSERT INTO public.publisher_payment_events(user_id,batch_id,kind,amount,reason,idempotency_key) VALUES(r.user_id,b.id,'estimated',b.gross,'Source earnings entered verification','batch:'||b.id); PERFORM public.payment_notify(r.user_id,'Earnings entered verification','Batch '||b.id||' is under quality verification.');
ELSIF b.gross<>r.gross THEN IF b.status='finalized' OR r.gross<b.adjustment THEN UPDATE public.publisher_earnings_batches SET reconciliation_open=true,status='on_hold' WHERE id=b.id; ELSE INSERT INTO public.publisher_payment_events(user_id,batch_id,kind,amount,reason,idempotency_key) VALUES(r.user_id,b.id,'estimate_revision',r.gross-b.gross,'Provider estimate reconciliation',gen_random_uuid()::text); UPDATE public.publisher_earnings_batches SET gross=r.gross,approved=false,verification_started_at=now(),verification_ends_at=greatest(verification_ends_at,now()+make_interval(days=>p.verification_days)) WHERE id=b.id; END IF; END IF; END LOOP;
UPDATE public.publisher_earnings_batches batch SET reconciliation_open=true,status='on_hold' WHERE batch.source IN ('website','smartlink') AND batch.period_start>=(p.effective_at AT TIME ZONE 'UTC')::date AND NOT EXISTS(SELECT 1 FROM public.revenue_events e WHERE batch.source='website' AND e.user_id=batch.user_id AND e.site_id IS NOT NULL AND e.date=batch.period_start) AND NOT EXISTS(SELECT 1 FROM public.network_stats n WHERE batch.source='smartlink' AND n.user_id=batch.user_id AND n.source='api' AND n.stat_date=batch.period_start);
END $$;